def warrant_info_complete(info: dict[str, Any]) -> bool:
    return bool(
        info.get("name")
        and info.get("underlyingCode")
        and to_number(info.get("strike")) is not None
        and to_number(info.get("ratio")) is not None
        and (info.get("exerciseEndDate") or info.get("lastTradingDate"))
    )


def fill_missing_warrant_info(info: dict[str, Any], fallback: dict[str, Any] | None) -> dict[str, Any]:
    if not fallback:
        return info
    for key, value in fallback.items():
        if info.get(key) in {None, ""} and value not in {None, ""}:
            info[key] = value
    return info


def apply_yuanta_overrides(info: dict[str, Any], yuanta: dict[str, Any] | None) -> None:
    if not yuanta:
        return
    info["name"] = yuanta.get("FLD_WAR_NM") or info.get("name") or ""
    if yuanta_type_is_put(yuanta):
        info["warrantType"] = "put"
    elif str(yuanta.get("FLD_WAR_TYPE") or "") in {"認購", "1", "CALL", "call"}:
        info["warrantType"] = "call"
    info["underlyingCode"] = yuanta.get("FLD_UND_ID") or info.get("underlyingCode") or ""
    info["underlyingName"] = yuanta.get("FLD_UND_NM") or info.get("underlyingName") or ""
    info["strike"] = first_number(yuanta.get("FLD_N_STRIKE_PRC"), info.get("strike"))
    info["ratio"] = first_number(yuanta.get("FLD_N_UND_CONVER"), info.get("ratio"))
    info["exerciseEndDate"] = compact_date_to_iso(yuanta.get("FLD_DUR_END")) or info.get("exerciseEndDate") or ""


def apply_kgi_overrides(info: dict[str, Any], kgi: dict[str, Any] | None) -> None:
    if not kgi:
        return
    info["name"] = kgi.get("INSTR_NAME") or info.get("name") or ""
    info["warrantType"] = "put" if kgi.get("INSWRT_CP") == "認售" else "call"
    info["underlyingCode"] = kgi.get("UND_INSTR_STKID") or info.get("underlyingCode") or ""
    info["underlyingName"] = kgi.get("UND_INSTR_NAME") or info.get("underlyingName") or ""
    info["strike"] = first_number(kgi.get("INSWRT_STRIKE"), info.get("strike"))
    info["ratio"] = first_number(kgi.get("INSWRT_EXECRATE"), info.get("ratio"))
    info["exerciseEndDate"] = compact_date_to_iso(kgi.get("INSWRT_EXPIRED_DATE")) or info.get("exerciseEndDate") or ""


@st.cache_data(ttl=REALTIME_QUOTE_TTL_SECONDS, show_spinner=False)
def fetch_quote(market: str, code: str) -> dict[str, Any] | None:
    params = {
        "ex_ch": f"{market}_{code}.tw",
        "json": "1",
        "delay": "0",
        "__": str(int(time.time() * 1000)),
    }
    endpoint = f"{TWSE_MIS}?{urlencode(params)}"
    return normalize_quote(fetch_json(endpoint), market, code)


def fetch_quote_with_fallback(code: str, preferred_market: str) -> dict[str, Any] | None:
    markets = ["tse", "otc"] if preferred_market == "tse" else ["otc", "tse"]
    with ThreadPoolExecutor(max_workers=2) as executor:
        futures = {market: executor.submit(fetch_quote, market, code) for market in markets}
        for market in markets:
            try:
                quote = futures[market].result()
            except Exception:
                quote = None
            if quote:
                return quote
    return None


def fetch_warrant_market_quote(code: str, preferred_market: str) -> dict[str, Any] | None:
    fugle_quote = None
    try:
        fugle_quote = fetch_fugle_quote(code, preferred_market)
    except Exception:
        fugle_quote = None
    if fugle_quote and market_bid_price(fugle_quote) is not None:
        return fugle_quote

    try:
        mis_quote = fetch_quote_with_fallback(code, preferred_market)
    except Exception:
        mis_quote = None
    if mis_quote and market_bid_price(mis_quote) is not None:
        return mis_quote
    return fugle_quote or mis_quote


def fugle_market(value: Any, fallback: str) -> str:
    text = str(value or "").lower()
    if "tpex" in text or "otc" in text or "roco" in text:
        return "otc"
    if "twse" in text or "tse" in text:
        return "tse"
    return fallback or "tse"


def value_from_path(source: Any, *keys: str) -> Any:
    value = source
    for key in keys:
        if not isinstance(value, dict):
            return None
        value = value.get(key)
    return value


def first_mapping_number(source: dict[str, Any], *keys: str) -> float | None:
    for key in keys:
        parsed = to_number(source.get(key))
        if parsed is not None:
            return parsed
    return None


def book_price(value: Any) -> float | None:
    if isinstance(value, list):
        for item in value:
            parsed = book_price(item)
            if parsed is not None:
                return parsed
    if isinstance(value, dict):
        return first_mapping_number(value, "price", "bid", "ask")
    if isinstance(value, (tuple, set)):
        for item in value:
            parsed = to_number(item)
            if parsed is not None:
                return parsed
    return to_number(value)


def normalize_fugle_quote(raw: dict[str, Any], requested_code: str, preferred_market: str) -> dict[str, Any] | None:
    data = raw.get("data") if isinstance(raw, dict) else None
    item = data if isinstance(data, dict) else raw if isinstance(raw, dict) else {}
    if not item:
        return None

    trade = item.get("trade") if isinstance(item.get("trade"), dict) else {}
    last = first_number(
        item.get("lastPrice"),
        item.get("last"),
        item.get("price"),
        trade.get("price"),
        item.get("closePrice"),
    )
    bids = item.get("bids") or value_from_path(item, "order", "bids") or item.get("bid")
    asks = item.get("asks") or value_from_path(item, "order", "asks") or item.get("ask")
    best_bid = first_number(
        item.get("bestBidPrice"),
        value_from_path(item, "bestBid", "price"),
        book_price(bids),
    )
    best_ask = first_number(
        item.get("bestAskPrice"),
        value_from_path(item, "bestAsk", "price"),
        book_price(asks),
    )
    if last is None and best_bid is None and best_ask is None:
        return None

    timestamp = (
        item.get("lastUpdated")
        or item.get("lastTradeTime")
        or item.get("lastTime")
        or trade.get("time")
        or item.get("time")
        or item.get("date")
        or ""
    )
    date_text = str(item.get("date") or item.get("tradeDate") or "")[:10].replace("-", "")
    time_text = str(timestamp or "")
    return {
        "market": fugle_market(item.get("exchange") or item.get("market"), preferred_market),
        "code": str(item.get("symbol") or requested_code),
        "name": item.get("name") or item.get("shortName") or "",
        "fullName": item.get("name") or item.get("shortName") or "",
        "relatedCode": "",
        "relatedName": "",
        "date": date_text,
        "time": time_text,
        "last": last,
        "recent": None,
        "price": last,
        "previousClose": to_number(item.get("previousClose") or item.get("referencePrice")),
        "open": to_number(item.get("openPrice")),
        "high": to_number(item.get("highPrice")),
        "low": to_number(item.get("lowPrice")),
        "bestBid": best_bid,
        "bestAsk": best_ask,
        "mid": (best_bid + best_ask) / 2 if best_bid is not None and best_ask is not None else None,
        "bidSize": [],
        "askSize": [],
        "rawStatus": "fugle",
    }


@st.cache_data(ttl=REALTIME_QUOTE_TTL_SECONDS, show_spinner=False)
def fetch_fugle_quote(code: str, preferred_market: str = "tse") -> dict[str, Any] | None:
    key = fugle_api_key()
    if not key:
        return None
    endpoint = FUGLE_INTRADAY_QUOTE.format(symbol=str(code or "").strip().upper())
    data = fetch_json(endpoint, headers={"X-API-KEY": key})
    return normalize_fugle_quote(data, code, preferred_market)


def market_candidates(preferred_market: str) -> list[str]:
    preferred = "otc" if preferred_market == "otc" else "tse"
    fallback = "tse" if preferred == "otc" else "otc"
    return [preferred, fallback]


def yahoo_symbols(code: str, preferred_market: str) -> list[tuple[str, str]]:
    markets = market_candidates(preferred_market)
    suffixes = {"tse": "TW", "otc": "TWO"}
    return [(f"{code}.{suffixes[market]}", market) for market in markets]


@st.cache_data(ttl=FALLBACK_QUOTE_TTL_SECONDS, show_spinner=False)
def fetch_yahoo_chart(symbol: str) -> dict[str, Any]:
    endpoint = YAHOO_CHART.format(symbol=symbol)
    params = {"range": "1d", "interval": "1m"}
    return fetch_json(f"{endpoint}?{urlencode(params)}")


def normalize_yahoo_quote(
    raw: dict[str, Any],
    requested_code: str,
    requested_market: str,
    symbol: str,
) -> dict[str, Any] | None:
    chart = raw.get("chart") if isinstance(raw, dict) else {}
    if not isinstance(chart, dict):
        return None
    error = chart.get("error")
    if error:
        description = error.get("description") if isinstance(error, dict) else str(error)
        raise WarrantError(f"{symbol} Yahoo 回傳錯誤：{description}")
    results = chart.get("result") or []
    result = results[0] if results else {}
    if not isinstance(result, dict):
        return None
    meta = result.get("meta") or {}
    indicators = result.get("indicators") or {}
    quote_blocks = indicators.get("quote") or []
    quote_block = quote_blocks[0] if quote_blocks else {}
    last, timestamp = latest_yahoo_trade(
        quote_block.get("close"),
        quote_block.get("volume"),
        result.get("timestamp"),
    )
    if last is None:
        return None
    quote_date = ""
    quote_time = ""
    if timestamp is not None:
        quoted_at = datetime.fromtimestamp(int(timestamp), TAIPEI)
        quote_date = quoted_at.strftime("%Y%m%d")
        quote_time = quoted_at.strftime("%H%M%S")
    return {
        "market": requested_market,
        "code": requested_code,
        "name": meta.get("shortName") or meta.get("longName") or "",
        "fullName": meta.get("longName") or meta.get("shortName") or "",
        "relatedCode": "",
        "relatedName": "",
        "date": quote_date,
        "time": quote_time,
        "last": last,
        "recent": last,
        "price": last,
        "previousClose": None,
        "open": to_number(meta.get("regularMarketOpen")),
        "high": to_number(meta.get("regularMarketDayHigh")),
        "low": to_number(meta.get("regularMarketDayLow")),
        "bestBid": None,
        "bestAsk": None,
        "mid": None,
        "bidSize": [],
        "askSize": [],
        "rawStatus": f"yahoo:{symbol}",
    }


def fetch_yahoo_underlying_quote(code: str, preferred_market: str) -> dict[str, Any] | None:
    errors: list[str] = []
    candidates = yahoo_symbols(code, preferred_market)
    with ThreadPoolExecutor(max_workers=2) as executor:
        futures = {symbol: executor.submit(fetch_yahoo_chart, symbol) for symbol, _ in candidates}
        results = []
        for symbol, market in candidates:
            try:
                results.append((symbol, market, futures[symbol].result(), None))
            except Exception as error:
                results.append((symbol, market, None, error))
    for symbol, market, raw, fetch_error in results:
        try:
            if fetch_error:
                raise fetch_error
            quote = normalize_yahoo_quote(raw, code, market, symbol)
        except Exception as error:
            errors.append(str(error))
            quote = None
        if quote and latest_trade_price(quote) is not None:
            return quote
        errors.append(f"{symbol} 無最新成交價")
    if errors:
        raise WarrantError("；".join(errors))
    return None


def fetch_exchange_underlying_quote(code: str, preferred_market: str) -> dict[str, Any] | None:
    errors: list[str] = []
    markets = market_candidates(preferred_market)
    with ThreadPoolExecutor(max_workers=2) as executor:
        futures = {market: executor.submit(fetch_quote, market, code) for market in markets}
        results = []
        for market in markets:
            try:
                results.append((market, futures[market].result(), None))
            except Exception as error:
                results.append((market, None, error))
    for market, quote, fetch_error in results:
        try:
            if fetch_error:
                raise fetch_error
        except Exception as error:
            errors.append(f"{market} MIS {error}")
            quote = None
        if quote and realtime_trade_price(quote) is not None:
            quote["rawStatus"] = quote.get("rawStatus") or "twse-mis"
            return quote
        errors.append(f"{market} MIS 無最新成交價")
    if errors:
        raise WarrantError("；".join(errors))
    return None


@st.cache_data(ttl=FALLBACK_QUOTE_TTL_SECONDS, show_spinner=False)
def fetch_underlying_market_quote(code: str, preferred_market: str) -> dict[str, Any]:
    normalized = str(code or "").strip().upper()
    if not normalized:
        raise WarrantError(f"{UNDERLYING_QUOTE_ERROR_MARK}：缺標的代號")

    errors: list[str] = []
    try:
        fugle_quote = fetch_fugle_quote(normalized, preferred_market)
    except Exception as error:
        fugle_quote = None
        errors.append(f"Fugle：{error}")
    if fugle_quote and realtime_trade_price(fugle_quote) is not None:
        return fugle_quote

    try:
        exchange_quote = fetch_exchange_underlying_quote(normalized, preferred_market)
    except Exception as error:
        exchange_quote = None
        errors.append(f"交易所 MIS：{error}")
    if exchange_quote and latest_trade_price(exchange_quote) is not None:
        return exchange_quote

    try:
        yahoo_quote = fetch_yahoo_underlying_quote(normalized, preferred_market)
    except Exception as error:
        yahoo_quote = None
        errors.append(f"Yahoo：{error}")
    if yahoo_quote and latest_trade_price(yahoo_quote) is not None:
        return yahoo_quote

    detail = "；".join(error for error in errors if error) or "所有來源無回應"
    raise WarrantError(f"{UNDERLYING_QUOTE_ERROR_MARK}：{normalized}（{detail}）")


def build_yuanta_calc_params(info: dict[str, Any], yuanta: dict[str, Any] | None, spot: Any) -> dict[str, str] | None:
    volatility = choose_yuanta_bid_volatility(yuanta)
    spot_value = to_number(spot)
    vol_value = to_number(volatility.get("value"))
    if not yuanta or not spot_value or not vol_value:
        return None

    expiry = (
        compact_date_to_iso(yuanta.get("FLD_DUR_END"))
        or info.get("exerciseEndDate")
        or info.get("lastTradingDate")
        or ""
    )
    return {
        "type": "calc",
        "symbol": str(info.get("code") or ""),
        "war_type": "2" if info.get("warrantType") == "put" else "1",
        "conver_rate": str(first_number(yuanta.get("FLD_N_UND_CONVER"), info.get("ratio")) or ""),
        "udly_price": str(spot_value),
        "bid_price": str(first_number(yuanta.get("FLD_WAR_BUY_PRICE")) or ""),
        "ask_price": str(first_number(yuanta.get("FLD_WAR_SELL_PRICE")) or ""),
        "strike_price": str(first_number(yuanta.get("FLD_N_STRIKE_PRC"), info.get("strike")) or ""),
        "hist_vol": str((first_number(yuanta.get("FLD_HISTORY_VOLATILITY_3M"), vol_value) or vol_value) / 100),
        "date_s": iso_to_compact(today_iso()),
        "date_e": iso_to_compact(expiry),
        "ir": str((first_number(yuanta.get("FLD_RISK_RATE_FREE"), 1.5) or 1.5) / 100),
        "iv": str(vol_value / 100),
    }


def build_yuanta_calc_params_from_item(item: dict[str, Any], spot: Any) -> dict[str, str] | None:
    spot_value = to_number(spot)
    if spot_value is None:
        return None

    params = dict(item.get("yuantaCalcParams") or {})
    if not params:
        quote = item.get("quote") or {}
        params = {
            "type": "calc",
            "symbol": str(item.get("code") or ""),
            "war_type": "2" if item.get("type") == "put" else "1",
            "conver_rate": str(to_number(item.get("ratio")) or ""),
            "bid_price": str(to_number(quote.get("bestBid")) or ""),
            "ask_price": str(to_number(quote.get("bestAsk")) or ""),
            "strike_price": str(to_number(item.get("strike")) or ""),
            "hist_vol": str(to_number(item.get("historyVolatility")) or to_number(item.get("volatility")) or ""),
            "date_s": iso_to_compact(today_iso()),
            "date_e": iso_to_compact(item.get("expiry")),
            "ir": str(to_number(item.get("riskFreeRate")) or 0.015),
            "iv": str(to_number(item.get("volatility")) or ""),
        }
    params["udly_price"] = str(spot_value)
    if not params.get("symbol") or not params.get("conver_rate") or not params.get("strike_price") or not params.get("date_e"):
        return None
    return params


def fetch_yuanta_fair_price(info: dict[str, Any], yuanta: dict[str, Any] | None, spot: Any) -> float | None:
    params = build_yuanta_calc_params(info, yuanta, spot)
    if not params:
        return None
    return fetch_yuanta_quote_price(params)


def fetch_yuanta_price_for_item(item: dict[str, Any], spot: Any) -> float | None:
    params = build_yuanta_calc_params_from_item(item, spot)
    if not params:
        return None
    return fetch_yuanta_quote_price(params)


def warrant_issuer(item: dict[str, Any]) -> str:
    text = " ".join(
        str(value or "")
        for value in (
            item.get("issuer"),
            item.get("name"),
            (item.get("quote") or {}).get("name"),
            (item.get("quote") or {}).get("fullName"),
        )
    )
    if "元大" in text:
        return "yuanta"
    if "凱基" in text:
        return "kgi"
    return ""


def issuer_label(issuer: str) -> str:
    if issuer == "yuanta":
        return "元大"
    if issuer == "kgi":
        return "凱基"
    return "未知券商"


def quote_reference(quote: dict[str, Any] | None) -> float | None:
    if not quote:
        return None
    return first_number(
        quote.get("mid"),
        quote.get("recent"),
        quote.get("last"),
        quote.get("bestBid"),
        quote.get("bestAsk"),
        quote.get("price"),
        quote.get("previousClose"),
    )


def market_bid_price(quote: dict[str, Any] | None) -> float | None:
    if not quote:
        return None
    return to_number(quote.get("bestBid"))


def latest_trade_price(quote: dict[str, Any] | None) -> float | None:
    if not quote:
        return None
    return first_number(quote.get("last"), quote.get("recent"))


def realtime_trade_price(quote: dict[str, Any] | None) -> float | None:
    if not quote:
        return None
    return to_number(quote.get("last"))


def quote_is_not_realtime(quote: dict[str, Any] | None) -> bool:
    return str((quote or {}).get("rawStatus") or "").lower().startswith("yahoo:")


def spot_price_from_underlying_quote(quote: dict[str, Any] | None) -> float | None:
    if quote_is_not_realtime(quote):
        return latest_trade_price(quote)
    return realtime_trade_price(quote)


def spot_source_note(item: dict[str, Any]) -> str:
    return "*not real time" if quote_is_not_realtime(item.get("underlyingQuote") or {}) else ""


def quote_is_blank(value: Any) -> bool:
    if value is None:
        return True
    if isinstance(value, str):
        return not value.strip()
    if isinstance(value, (list, tuple, dict)):
        return not value
    return False


def merge_quote(primary: dict[str, Any] | None, fallback: dict[str, Any] | None) -> dict[str, Any] | None:
    if not primary:
        return fallback
    if not fallback:
        return primary
    merged = dict(primary)
    for key, value in fallback.items():
        if key == "rawStatus":
            continue
        if key == "market" and not quote_is_blank(value):
            merged[key] = value
        elif quote_is_blank(merged.get(key)) and not quote_is_blank(value):
            merged[key] = value
    return merged


def quote_without_market_prices(quote: dict[str, Any] | None) -> dict[str, Any] | None:
    if not quote:
        return None
    cleaned = dict(quote)
    for key in MARKET_QUOTE_FIELDS:
        if key in {"bidSize", "askSize"}:
            cleaned[key] = []
        elif key in {"date", "time"}:
            cleaned[key] = ""
        else:
            cleaned[key] = None
    return cleaned


def merge_quote_metadata(
    market_quote: dict[str, Any] | None,
    metadata_quote: dict[str, Any] | None,
) -> dict[str, Any] | None:
    if not market_quote:
        return quote_without_market_prices(metadata_quote)
    if not metadata_quote:
        return market_quote
    merged = dict(market_quote)
    for key, value in metadata_quote.items():
        if key in MARKET_QUOTE_FIELDS or key == "rawStatus":
            continue
        if quote_is_blank(merged.get(key)) and not quote_is_blank(value):
            merged[key] = value
    return merged


def mark_underlying_quote_error(item: dict[str, Any], message: str) -> None:
    item["spot"] = None
    item["underlyingQuote"] = quote_without_market_prices(item.get("underlyingQuote") or {})
    item["error"] = message


def clear_underlying_quote_error(item: dict[str, Any]) -> None:
    if UNDERLYING_QUOTE_ERROR_MARK in str(item.get("error") or ""):
        item["error"] = ""


def append_item_error(item: dict[str, Any], message: str) -> None:
    text = str(message or "").strip()
    if not text:
        return
    existing = str(item.get("error") or "").strip()
    if text in existing:
        return
    item["error"] = f"{existing}；{text}" if existing else text


