def implied_spot_from_price(item: dict[str, Any], target_price: Any) -> float | None:
    target = to_number(target_price)
    strike = to_number(item.get("strike"))
    spot = first_number(item.get("spot"), strike)
    if target is None or target < 0 or not strike or not spot:
        return None

    is_put = item.get("type") == "put"
    low = 0.01
    high = max(strike, spot, 1) * 2

    def price_at(value: float) -> float:
        return fair_price_for_spot(item, value) or 0

    if is_put:
        while price_at(low) < target and low > 0.000001:
            low /= 2
        while price_at(high) > target and high < strike * 20:
            high *= 2
        if price_at(low) < target or price_at(high) > target:
            return None
        for _ in range(7):
            mid = (low + high) / 2
            if price_at(mid) > target:
                low = mid
            else:
                high = mid
        return (low + high) / 2

    while price_at(high) < target and high < strike * 20:
        high *= 2
    if price_at(low) > target or price_at(high) < target:
        return None
    for _ in range(7):
        mid = (low + high) / 2
        if price_at(mid) < target:
            low = mid
        else:
            high = mid
    return (low + high) / 2


def load_warrant(code: str, existing: dict[str, Any] | None = None) -> dict[str, Any]:
    normalized = str(code or "").strip().upper()
    if not re.fullmatch(r"[0-9A-Z]+", normalized):
        raise WarrantError("請輸入有效權證代號")
    if re.fullmatch(r"\d{4}", normalized):
        raise WarrantError("請輸入權證代號，不是股票代號；例如 068562")

    exchange_error = ""
    yuanta_error = ""
    kgi_error = ""
    market_quote: dict[str, Any] | None = None
    yuanta: dict[str, Any] | None = None
    kgi_warrant: dict[str, Any] | None = None
    existing_info = info_from_existing_item(normalized, existing)
    if existing_info:
        info = existing_info
        issuer = warrant_issuer({"issuer": (existing or {}).get("issuer"), "name": info.get("name")})
        with ThreadPoolExecutor(max_workers=2) as executor:
            market_future = executor.submit(
                fetch_warrant_market_quote,
                normalized,
                info.get("warrantMarket") or "tse",
            )
            broker_future = None
            if issuer == "yuanta":
                broker_future = executor.submit(fetch_yuanta_warrant, normalized)
            elif issuer == "kgi":
                broker_future = executor.submit(fetch_kgi_warrant, normalized)
            try:
                market_quote = market_future.result()
            except Exception as error:
                exchange_error = str(error)
            if broker_future:
                try:
                    broker_result = broker_future.result()
                    if issuer == "yuanta":
                        yuanta = broker_result
                    else:
                        kgi_warrant = broker_result
                except Exception as error:
                    if issuer == "yuanta":
                        yuanta_error = str(error)
                    else:
                        kgi_error = str(error)
    else:
        info = empty_warrant_info(normalized)
        with ThreadPoolExecutor(max_workers=2) as executor:
            market_future = executor.submit(fetch_warrant_market_quote, normalized, "tse")
            yuanta_future = executor.submit(fetch_yuanta_warrant, normalized)
            try:
                market_quote = market_future.result()
            except Exception as error:
                exchange_error = str(error)
                market_quote = None
            try:
                yuanta = yuanta_future.result()
            except Exception as error:
                yuanta_error = str(error)
                yuanta = None

        if market_quote:
            info = info_from_quote(normalized, market_quote)
        issuer = "yuanta" if yuanta else warrant_issuer({"name": info.get("name")})
        if issuer == "kgi" or not issuer:
            try:
                kgi_warrant = fetch_kgi_warrant(normalized)
                if kgi_warrant:
                    issuer = "kgi"
            except Exception as error:
                kgi_error = str(error)
                kgi_warrant = None

    issuer = warrant_issuer(
        {
            "issuer": (existing or {}).get("issuer") or issuer,
            "name": info.get("name") or (market_quote or {}).get("name") or (market_quote or {}).get("fullName"),
        }
    )
    if yuanta:
        issuer = "yuanta"
        apply_yuanta_overrides(info, yuanta)
    elif kgi_warrant:
        issuer = "kgi"
        apply_kgi_overrides(info, kgi_warrant)

    if not existing_info and not warrant_info_complete(info):
        try:
            fill_missing_warrant_info(info, find_warrant_info(normalized))
        except Exception as error:
            exchange_error = exchange_error or str(error)

    broker_quote = None
    quote = None
    market_underlying_quote = None
    underlying_error = ""

    if issuer == "yuanta" and not yuanta:
        yuanta_error = yuanta_error or "元大資料讀不到這檔權證"
    elif issuer == "kgi" and not kgi_warrant:
        kgi_error = kgi_error or "凱基資料讀不到這檔權證"

    if issuer == "yuanta":
        broker_quote = quote_from_yuanta(yuanta, normalized, info.get("warrantMarket") or "tse")
    elif issuer == "kgi":
        broker_quote = quote_from_kgi(kgi_warrant, normalized)
    else:
        broker_quote = None

    quote = merge_quote_metadata(market_quote, broker_quote)
    market_reference = market_bid_price(market_quote)
    market_reference_error = ""
    if market_reference is None:
        detail = exchange_error or "交易所 MIS 無第一檔委買"
        market_reference_error = f"{WARRANT_MARKET_BID_ERROR_MARK}：{normalized}（{detail}）"

    if not quote:
        details = "；".join(message for message in (yuanta_error, kgi_error, exchange_error) if message)
        raise WarrantError(f"查無權證即時報價{f'：{details}' if details else ''}")

    info = info_from_quote(normalized, quote) | info
    info["warrantMarket"] = quote.get("market") or info.get("warrantMarket") or "tse"
    info["underlyingCode"] = info.get("underlyingCode") or quote.get("relatedCode") or ""
    info["underlyingName"] = info.get("underlyingName") or quote.get("relatedName") or ""

    if issuer == "yuanta":
        if not yuanta:
            yuanta_error = yuanta_error or "元大資料讀不到這檔權證"
    elif issuer == "kgi":
        if not kgi_warrant:
            kgi_error = kgi_error or "凱基資料讀不到這檔權證"

    if not info.get("underlyingCode") and info.get("underlyingName"):
        try:
            underlying = find_underlying(info["underlyingName"])
        except Exception:
            underlying = None
        if underlying:
            info["underlyingCode"] = underlying.get("Code") or ""
            info["underlyingName"] = underlying.get("Name") or info.get("underlyingName") or ""
            info["underlyingMarket"] = "tse"

    broker_underlying_quote = underlying_quote_from_kgi(kgi_warrant, None) or underlying_quote_from_yuanta(
        yuanta,
        info.get("underlyingMarket") or info.get("warrantMarket") or "tse",
    )
    prefetched_code = str((market_underlying_quote or {}).get("code") or "").strip().upper()
    expected_code = str(info.get("underlyingCode") or "").strip().upper()
    if expected_code and prefetched_code != expected_code:
        try:
            market_underlying_quote = fetch_underlying_market_quote(
                expected_code,
                info.get("underlyingMarket") or info.get("warrantMarket") or "tse",
            )
        except Exception as error:
            underlying_error = str(error)
            market_underlying_quote = None
    elif not expected_code:
        underlying_error = f"{UNDERLYING_QUOTE_ERROR_MARK}：缺標的代號"
    underlying_quote = merge_quote_metadata(market_underlying_quote, broker_underlying_quote)
    if not market_underlying_quote or spot_price_from_underlying_quote(market_underlying_quote) is None:
        raise WarrantError(underlying_error or "查無標的最新成交價")
    if not underlying_quote:
        raise WarrantError(underlying_error or "查無標的即時報價")

    info["underlyingMarket"] = underlying_quote.get("market") or info.get("underlyingMarket")
    info["underlyingName"] = info.get("underlyingName") or underlying_quote.get("name") or ""

    yuanta_volatility = choose_yuanta_bid_volatility(yuanta)
    if issuer == "kgi":
        volatility = {
            "value": first_number((kgi_warrant or {}).get("MTM_BID_VOL")),
            "source": "凱基委買波動率" if first_number((kgi_warrant or {}).get("MTM_BID_VOL")) else "",
        }
        underlying_price = spot_price_from_underlying_quote(underlying_quote)
        risk_free_rate = 1.5
        history_volatility = to_number((kgi_warrant or {}).get("THREE_MONTH_HISTORY_VOLAILITY"))
    else:
        volatility = yuanta_volatility
        underlying_price = spot_price_from_underlying_quote(underlying_quote)
        risk_free_rate = first_number((yuanta or {}).get("FLD_RISK_RATE_FREE"), 1.5)
        history_volatility = to_number((yuanta or {}).get("FLD_HISTORY_VOLATILITY_3M"))
    pricing = {
        "evaluationDate": today_iso(),
        "underlyingPrice": underlying_price,
        "volatility": volatility.get("value"),
        "volatilitySource": volatility.get("source"),
        "riskFreeRate": risk_free_rate,
        "historyVolatility": history_volatility,
        "expiryDate": info.get("exerciseEndDate") or info.get("lastTradingDate") or "",
    }
    yuanta_missing_fields: list[str] = []
    if issuer == "yuanta":
        if underlying_price is None:
            yuanta_missing_fields.append("標的價")
        if to_number(volatility.get("value")) is None:
            yuanta_missing_fields.append("隱波")
        if to_number(info.get("strike")) is None:
            yuanta_missing_fields.append("履約價")
        if to_number(info.get("ratio")) is None:
            yuanta_missing_fields.append("換股比")
        if not pricing["expiryDate"]:
            yuanta_missing_fields.append("到期日")
    yuanta_calc_params = build_yuanta_calc_params(info, yuanta, underlying_price) if issuer == "yuanta" else None
    fair_from_yuanta = None
    if issuer == "yuanta":
        try:
            fair_from_yuanta = valid_price(fetch_yuanta_quote_price(yuanta_calc_params)) if yuanta_calc_params else None
        except Exception as error:
            yuanta_error = str(error)
    kgi_calc_params: dict[str, Any] = {}
    fair_from_kgi = None
    if issuer == "kgi":
        try:
            kgi_calc_params = build_kgi_calc_params_from_warrant(kgi_warrant or {}, underlying_price) or {}
            fair_from_kgi = valid_price(fetch_kgi_theoretical_price(kgi_calc_params))
        except Exception as error:
            kgi_error = str(error)
            fair_from_kgi = None

    spot = spot_price_from_underlying_quote(underlying_quote)
    item = {
        "id": (existing or {}).get("id") or str(uuid.uuid4()),
        "code": info.get("code") or normalized,
        "name": info.get("name") or "",
        "issuer": issuer,
        "type": info.get("warrantType") or "call",
        "expiry": pricing["expiryDate"],
        "strike": info.get("strike"),
        "ratio": info.get("ratio"),
        "underlyingCode": info.get("underlyingCode") or "",
        "underlyingName": info.get("underlyingName") or "",
        "quote": quote,
        "underlyingQuote": underlying_quote,
        "spot": spot,
        "marketReference": market_reference,
        "volatility": (pricing["volatility"] / 100) if pricing.get("volatility") is not None else None,
        "volatilitySource": pricing.get("volatilitySource") or "委買隱波",
        "historyVolatility": (pricing.get("historyVolatility") / 100) if pricing.get("historyVolatility") else None,
        "riskFreeRate": (first_number(pricing["riskFreeRate"], 1.5) or 1.5) / 100,
        "evaluationDate": pricing.get("evaluationDate") or "",
        "yuantaCalcParams": yuanta_calc_params or {},
        "kgiCalcParams": kgi_calc_params,
        "testSpot": "",
        "targetPrice": "",
        "updatedAt": int(time.time() * 1000),
        "error": "",
    }
    if issuer == "yuanta":
        item["fairPrice"] = fair_from_yuanta
    elif issuer == "kgi":
        item["fairPrice"] = fair_from_kgi
    else:
        item["fairPrice"] = None

    if issuer == "yuanta" and fair_from_yuanta is not None:
        item["fairPriceSource"] = "元大合理價"
    elif issuer == "kgi" and fair_from_kgi is not None:
        item["fairPriceSource"] = "凱基理論價"
    elif issuer == "yuanta":
        item["fairPriceSource"] = "元大合理價抓取失敗"
        item["error"] = yuanta_error or (
            f"缺{', '.join(yuanta_missing_fields)}，無法推估元大合理價"
            if yuanta_missing_fields
            else "元大合理價抓取失敗"
        )
    elif issuer == "kgi":
        item["fairPriceSource"] = "凱基理論價抓取失敗"
        item["error"] = kgi_error or "凱基理論價抓取失敗"
    else:
        item["fairPriceSource"] = "不支援券商"
        item["error"] = "目前只支援元大與凱基權證理論價"
    append_item_error(item, market_reference_error)
    item["simulatedPrice"] = None
    item["impliedSpot"] = None
    return apply_volatility_tracking(item, existing)


def fair_price_for_spot(item: dict[str, Any], spot: Any) -> float | None:
    spot_value = to_number(spot)
    if spot_value is None:
        return None
    issuer = warrant_issuer(item)
    if issuer == "yuanta":
        return valid_price(fetch_yuanta_price_for_item(item, spot_value))
    if issuer == "kgi":
        return valid_price(fetch_kgi_price_for_item(item, spot_value))
    return None


def read_cloud_items() -> list[dict[str, Any]]:
    try:
        items = read_supabase_items()
    except Exception as error:
        st.error(f"Supabase 清單讀取失敗：{error}")
        return []
    valid_items: list[dict[str, Any]] = []
    for item in items:
        if isinstance(item, dict) and item.get("code"):
            item.setdefault("id", str(uuid.uuid4()))
            item.setdefault("error", "")
            item.setdefault("volatilityAlerted", False)
            item.setdefault("previousVolatility", None)
            item.setdefault("volatilityChangePoints", None)
            item.setdefault("volatilityHistory", [])
            valid_items.append(recalculate_derived_prices(item))
    return valid_items


def clear_item_calculations(item: dict[str, Any]) -> dict[str, Any]:
    for field in CALCULATION_FIELDS:
        item[field] = "" if field in {"testSpot", "targetPrice"} else None
    return item


def item_without_calculations(item: dict[str, Any]) -> dict[str, Any]:
    payload = clear_item_calculations(dict(item))
    payload.pop("pricingVolatility", None)
    return payload


def write_cloud_items(items: list[dict[str, Any]]) -> None:
    write_supabase_items(items)


def recalculate_derived_prices(item: dict[str, Any]) -> dict[str, Any]:
    return clear_item_calculations(item)


def normalize_saved_item(item: dict[str, Any]) -> dict[str, Any] | None:
    code = str(item.get("code") or "").strip().upper()
    if not code:
        return None
    normalized = dict(item)
    normalized["code"] = code
    normalized.setdefault("id", str(uuid.uuid4()))
    normalized.setdefault("error", "")
    normalized.setdefault("type", "call")
    normalized.setdefault("quote", {})
    normalized.setdefault("underlyingQuote", {})
    normalized.setdefault("volatilityAlerted", False)
    normalized.setdefault("previousVolatility", None)
    normalized.setdefault("volatilityChangePoints", None)
    normalized.setdefault("volatilityHistory", [])
    normalized.setdefault("testSpot", normalized.get("spot"))
    normalized.setdefault("targetPrice", normalized.get("marketReference"))
    normalized.setdefault("updatedAt", int(time.time() * 1000))
    return recalculate_derived_prices(normalized)


def parse_import_items(raw_text: str) -> list[dict[str, Any]]:
    text = raw_text.strip()
    if not text:
        raise ValueError("請貼上舊版 localStorage 內容")

    payload = json.loads(text)
    if isinstance(payload, str):
        payload = json.loads(payload)
    if isinstance(payload, dict):
        if isinstance(payload.get("warrant-watch-items-v3"), str):
            payload = json.loads(payload["warrant-watch-items-v3"])
        elif isinstance(payload.get("items"), list):
            payload = payload["items"]
    if not isinstance(payload, list):
        raise ValueError("匯入內容不是權證清單格式")

    imported: list[dict[str, Any]] = []
    for item in payload:
        if isinstance(item, dict):
            normalized = normalize_saved_item(item)
            if normalized:
                imported.append(normalized)
    if not imported:
        raise ValueError("沒有讀到任何權證代號")
    return imported


def import_items(raw_text: str, *, replace: bool) -> int:
    imported = parse_import_items(raw_text)
    if replace:
        st.session_state["items"] = imported
    else:
        by_code = {item.get("code"): index for index, item in enumerate(st.session_state["items"])}
        for item in imported:
            found_index = by_code.get(item["code"])
            if found_index is None:
                by_code[item["code"]] = len(st.session_state["items"])
                st.session_state["items"].append(item)
            else:
                st.session_state["items"][found_index] = item
    persist_current_items()
    return len(imported)


def export_items_text() -> str:
    payload = {
        "exportedAt": datetime.now(TAIPEI).isoformat(),
        "appVersion": APP_VERSION,
        "items": [item_without_calculations(item) for item in st.session_state.get("items", [])],
    }
    return json.dumps(payload, ensure_ascii=False, indent=2)


def format_number(value: Any, digits: int = 2) -> str:
    parsed = to_number(value)
    if parsed is None:
        return "--"
    return f"{parsed:,.{digits}f}"


def format_metric_number(value: Any, digits: int = 2, *, missing: str = "--") -> str:
    parsed = to_number(value)
    if parsed is None:
        return missing
    return f"{parsed:,.{digits}f}"


def valid_price(value: Any) -> float | None:
    parsed = to_number(value)
    if parsed is None or parsed <= 0:
        return None
    return parsed


def format_input_number(value: Any, digits: int = 2) -> str:
    parsed = to_number(value)
    if parsed is None:
        return ""
    return f"{parsed:.{digits}f}"


def format_calc_number(value: Any, digits: int = 2) -> str:
    parsed = to_number(value)
    if parsed is None:
        return ""
    return f"{parsed:,.{digits}f}"


def numbers_equal(left: Any, right: Any, *, tolerance: float = 1e-9) -> bool:
    left_number = to_number(left)
    right_number = to_number(right)
    if left_number is None or right_number is None:
        return left_number is right_number
    return abs(left_number - right_number) <= tolerance


def type_text(value: str) -> str:
    return "認售" if value == "put" else "認購"


def format_percent_points(value: Any, digits: int = 2) -> str:
    parsed = to_number(value)
    if parsed is None:
        return "--"
    return f"{parsed * 100:,.{digits}f}%"


def format_volatility_change(value: Any) -> str:
    parsed = to_number(value)
    if parsed is None:
        return "--"
    sign = "+" if parsed > 0 else ""
    return f"{sign}{parsed:.2f}%"


def normalize_volatility_history(value: Any) -> list[dict[str, Any]]:
    if not isinstance(value, list):
        return []
    history: list[dict[str, Any]] = []
    for entry in value:
        if not isinstance(entry, dict):
            continue
        previous = to_number(entry.get("previousVolatility"))
        current = to_number(entry.get("currentVolatility"))
        change = to_number(entry.get("changePoints"))
        changed_at = str(entry.get("changedAt") or "").strip()
        if previous is None or current is None or change is None or not changed_at:
            continue
        history.append(
            {
                "changedAt": changed_at,
                "previousVolatility": previous,
                "currentVolatility": current,
                "changePoints": change,
                "direction": entry.get("direction") or ("up" if change > 0 else "down" if change < 0 else "flat"),
            }
        )
    return history


def format_tracking_time(value: Any) -> str:
    text = str(value or "").strip()
    if not text:
        return ""
    try:
        parsed = datetime.fromisoformat(text)
    except ValueError:
        digits = re.sub(r"\D", "", text)
        return digits[:8] if len(digits) >= 8 else ""
    return parsed.strftime("%Y%m%d")


def migrate_legacy_volatility_history(existing: dict[str, Any], history: list[dict[str, Any]]) -> list[dict[str, Any]]:
    if history or not existing.get("volatilityAlerted"):
        return history

    current = to_number(existing.get("volatility"))
    previous = to_number(existing.get("previousVolatility"))
    change = to_number(existing.get("volatilityChangePoints"))
    if previous is None and current is not None and change is not None:
        previous = current - (change / 100)
    if change is None and previous is not None and current is not None:
        change = (current - previous) * 100
    changed_at = (
        existing.get("volatilityLastAlertAt")
        or existing.get("volatilityFirstAlertAt")
        or existing.get("volatilityLastCheckAt")
        or ""
    )
    if previous is None or current is None or change is None:
        return history
    return [
        {
            "changedAt": str(changed_at),
            "previousVolatility": previous,
            "currentVolatility": current,
            "changePoints": change,
            "direction": existing.get("volatilityDirection") or ("up" if change > 0 else "down" if change < 0 else "flat"),
        }
    ]


def apply_volatility_tracking(item: dict[str, Any], existing: dict[str, Any] | None) -> dict[str, Any]:
    existing = existing or {}
    current_volatility = to_number(item.get("volatility"))
    previous_volatility = to_number(existing.get("volatility"))
    current_source = str(item.get("volatilitySource") or "")
    previous_source = str(existing.get("volatilitySource") or "")
    previous_alerted = bool(existing.get("volatilityAlerted"))
    history = migrate_legacy_volatility_history(
        existing,
        normalize_volatility_history(existing.get("volatilityHistory")),
    )
    last_record = history[-1] if history else {}
    last_recorded_volatility = to_number(last_record.get("currentVolatility"))
    now = today_compact()

    item["volatilityAlerted"] = previous_alerted
    item["volatilityAlertThreshold"] = VOLATILITY_ALERT_POINTS
    item["volatilityHistory"] = history
    item["previousVolatility"] = existing.get("previousVolatility")
    item["volatilityChangePoints"] = existing.get("volatilityChangePoints")
    item["volatilityDirection"] = existing.get("volatilityDirection") or ""
    item["volatilityFirstAlertAt"] = existing.get("volatilityFirstAlertAt") or ""
    item["volatilityLastAlertAt"] = existing.get("volatilityLastAlertAt") or ""
    item["volatilityLastCheckAt"] = now

    if previous_source and current_source and previous_source != current_source:
        item["volatilityAlerted"] = False
        item["previousVolatility"] = current_volatility
        item["volatilityChangePoints"] = 0
        item["volatilityDirection"] = "flat"
        return item

    baseline_volatility = last_recorded_volatility
    if baseline_volatility is None:
        baseline_volatility = to_number(existing.get("volatility"))
    if baseline_volatility is None:
        baseline_volatility = previous_volatility
    if current_volatility is None or baseline_volatility is None:
        return item

    change_points = (current_volatility - baseline_volatility) * 100
    if abs(change_points) >= VOLATILITY_ALERT_POINTS:
        direction = "up" if change_points > 0 else "down" if change_points < 0 else "flat"
        item["volatilityAlerted"] = True
        item["previousVolatility"] = baseline_volatility
        item["volatilityChangePoints"] = change_points
        item["volatilityDirection"] = direction
        item["volatilityLastAlertAt"] = now
        if not item["volatilityFirstAlertAt"]:
            item["volatilityFirstAlertAt"] = now
        if last_recorded_volatility is None or not numbers_equal(current_volatility, last_recorded_volatility, tolerance=0.0000001):
            item["volatilityHistory"].append(
                {
                    "changedAt": now,
                    "previousVolatility": baseline_volatility,
                    "currentVolatility": current_volatility,
                    "changePoints": change_points,
                    "direction": direction,
                }
            )
    return item


def volatility_tracking_text(item: dict[str, Any]) -> str:
    history = normalize_volatility_history(item.get("volatilityHistory"))
    if history:
        last = history[-1]
        return (
            f"已記錄 {len(history)} 筆 / "
            f"上次 {format_tracking_time(last.get('changedAt'))} / "
            f"變化 {format_volatility_change(last.get('changePoints'))}"
        )
    previous = to_number(item.get("previousVolatility"))
    change = to_number(item.get("volatilityChangePoints"))
    if previous is None or change is None:
        return "尚無前次資料"
    return f"前次 {format_percent_points(previous)} / 變化 {format_volatility_change(change)}"


def volatility_history_detail_text(entry: dict[str, Any]) -> str:
    previous = format_percent_points(entry.get("previousVolatility"))
    current = format_percent_points(entry.get("currentVolatility"))
    change = format_volatility_change(entry.get("changePoints"))
    changed_at = format_tracking_time(entry.get("changedAt"))
    return f"{changed_at} {previous} -> {current} ({change})"


def volatility_detail_text(item: dict[str, Any]) -> str:
    source = item.get("volatilitySource") or "委買隱波"
    value = to_number(item.get("volatility"))
    return f"{source} {format_percent_points(value)}"


def time_ago(timestamp: Any) -> str:
    parsed = to_number(timestamp)
    if parsed is None:
        return "未更新"
    seconds = max(0, int((time.time() * 1000 - parsed) / 1000))
    if seconds < 60:
        return f"{seconds} 秒前"
    minutes = seconds // 60
    if minutes < 60:
        return f"{minutes} 分前"
    return f"{minutes // 60} 小時前"


def latest_update_text(items: list[dict[str, Any]]) -> str:
    latest = max((to_number(item.get("updatedAt")) or 0 for item in items), default=0)
    return time_ago(latest) if latest else "尚未更新"


