def detail_html(item: dict[str, Any]) -> str:
    quote = item.get("quote") or {}
    underlying_quote = item.get("underlyingQuote") or {}
    volatility_history = normalize_volatility_history(item.get("volatilityHistory"))
    if len(volatility_history) >= 2:
        star_class = "native-detail-popover volatility-alert"
    elif item.get("volatilityAlerted"):
        star_class = "native-detail-popover volatility-lit"
    else:
        star_class = "native-detail-popover"
    star_text = "★" if item.get("volatilityAlerted") else "☆"
    star_title = "隱波已變動，點擊查看追蹤" if item.get("volatilityAlerted") else "權證細節"
    rows = [
        ("類型", type_text(item.get("type") or "call")),
        ("標的", f"{item.get('underlyingCode') or ''} {item.get('underlyingName') or ''}".strip()),
        ("履約價", format_number(item.get("strike"))),
        ("換股比例", format_number(item.get("ratio"), 4)),
        ("到期日", item.get("expiry") or "--"),
        ("評價日", item.get("evaluationDate") or "--"),
        ("合理價來源", item.get("fairPriceSource") or "--"),
        ("委買隱波", volatility_detail_text(item)),
        ("隱波追蹤", volatility_tracking_text(item)),
        ("利率", f"{format_number((to_number(item.get('riskFreeRate')) or 0) * 100)}%"),
        ("委買/委賣", f"{format_number(quote.get('bestBid'))} / {format_number(quote.get('bestAsk'))}"),
        ("標的市場", f"{underlying_quote.get('market') or '--'}"),
    ]
    for record_index, entry in enumerate(reversed(volatility_history), start=1):
        rows.append((f"變動 {record_index}", volatility_history_detail_text(entry)))
    body = "".join(detail_row_html(label, value) for label, value in rows)
    return (
        f'<details class="{star_class}">'
        f'<summary title="{html.escape(star_title)}">{star_text}</summary>'
        f'<div class="native-detail-body">{body}</div>'
        "</details>"
    )


def cancel_pending_order_sync() -> None:
    timer = st.session_state.pop("_order_sync_timer", None)
    if isinstance(timer, threading.Timer):
        timer.cancel()
    cancel_event = st.session_state.pop("_order_sync_cancel_event", None)
    if isinstance(cancel_event, threading.Event):
        cancel_event.set()
    st.session_state["_pending_order_sync"] = False


def session_cloud_sync_lock() -> threading.Lock:
    lock = st.session_state.get("_cloud_sync_lock")
    if lock is None:
        lock = threading.Lock()
        st.session_state["_cloud_sync_lock"] = lock
    return lock


def run_delayed_order_sync(
    items: list[dict[str, Any]],
    config: dict[str, str],
    cancel_event: threading.Event,
    sync_lock: threading.Lock,
) -> None:
    with sync_lock:
        if cancel_event.is_set():
            return
        try:
            write_supabase_items_with_config(items, config)
        except Exception:
            return


def schedule_items_sync(delay_seconds: float) -> None:
    cancel_pending_order_sync()
    config = supabase_config()
    if not config:
        raise WarrantError("Supabase 尚未設定，無法儲存清單")
    cancel_event = threading.Event()
    sync_lock = session_cloud_sync_lock()
    timer = threading.Timer(
        delay_seconds,
        run_delayed_order_sync,
        args=(copy.deepcopy(st.session_state["items"]), dict(config), cancel_event, sync_lock),
    )
    timer.daemon = True
    st.session_state["_order_sync_timer"] = timer
    st.session_state["_order_sync_cancel_event"] = cancel_event
    st.session_state["_pending_order_sync"] = True
    timer.start()


def schedule_order_sync() -> None:
    schedule_items_sync(ORDER_SYNC_DELAY_SECONDS)


def persist_current_items() -> None:
    cancel_pending_order_sync()
    with session_cloud_sync_lock():
        write_cloud_items(st.session_state["items"])


