def render_warrant_card(item: dict[str, Any], index: int) -> None:
    card_id = safe_key(item.get("id") or item.get("code") or str(index))
    with st.container(border=True, key=f"card_{card_id}"):
        card_cols = st.columns([1.0, 0.14], gap="small")

        changed = False
        with card_cols[1]:
            with st.container(key=f"card_actions_{card_id}"):
                st.markdown('<div class="desktop-action-spacer"></div>', unsafe_allow_html=True)
                with st.container(key=f"btn_grid_{card_id}"):
                    btn_l, btn_r = st.columns(2)
                    with btn_l:
                        with st.container(key=f"card_action_up_{card_id}"):
                            if st.button("▲", key=f"up_{card_id}", disabled=index == 0, help="上移"):
                                move_item(index, -1)
                        with st.container(key=f"card_action_down_{card_id}"):
                            if st.button("▼", key=f"dn_{card_id}", disabled=index == len(st.session_state["items"]) - 1, help="下移"):
                                move_item(index, 1)
                    with btn_r:
                        with st.container(key=f"reset_{card_id}"):
                            with st.popover("↺", help="重置隱波紀錄"):
                                st.markdown("<div style='text-align: center; margin-bottom: 0.5rem; font-size: 0.85rem;'>確定重置隱波？</div>", unsafe_allow_html=True)
                                if st.button("確認", key=f"confirm_reset_{card_id}", use_container_width=True):
                                    reset_volatility_tracking(st.session_state["items"][index])
                                    st.rerun()
                        with st.container(key=f"delete_{card_id}"):
                            with st.popover("×", help="刪除這檔權證"):
                                st.markdown("<div style='text-align: center; margin-bottom: 0.5rem; font-size: 0.85rem;'>確定刪除？</div>", unsafe_allow_html=True)
                                if st.button("確認", key=f"confirm_del_{card_id}", use_container_width=True):
                                    delete_item(index)

        with card_cols[0]:
            st.markdown(
                '<div class="card-header-grid">'
                '<div class="card-title-cell">'
                f"{warrant_title_html(item)}"
                f"{detail_html(item)}"
                "</div>"
                + metric_html("合理價", valid_price(item.get("fairPrice")), accent=True, missing="---")
                + metric_html("報價", item.get("marketReference"))
                + metric_html("現貨股價", item.get("spot"), note=spot_source_note(item))
                + "</div>",
                unsafe_allow_html=True,
            )

            calc_cols = st.columns(2, gap="small")
            with calc_cols[0]:
                with st.container(key=f"calc_forward_{card_id}"):
                    inner = st.columns([0.95, 1.05], gap="small")
                    spot_key = f"spot_text_{card_id}"
                    if spot_key not in st.session_state:
                        st.session_state[spot_key] = format_input_number(item.get("testSpot"))
                    with inner[0]:
                        test_spot_raw = st.text_input("股價", key=spot_key)
                    test_spot = to_number(test_spot_raw)
                    if test_spot is None:
                        simulated = None
                        if to_number(item.get("testSpot")) is not None or to_number(item.get("simulatedPrice")) is not None:
                            item["testSpot"] = ""
                            item["simulatedPrice"] = None
                            changed = True
                    else:
                        if numbers_equal(test_spot, item.get("testSpot")) and to_number(item.get("simulatedPrice")) is not None:
                            simulated = item.get("simulatedPrice")
                        elif numbers_equal(test_spot, item.get("spot")):
                            simulated = valid_price(item.get("fairPrice"))
                            changed = True
                        else:
                            simulated = fair_price_for_spot(item, test_spot)
                            changed = True
                        if changed:
                            item["testSpot"] = test_spot
                            item["simulatedPrice"] = simulated
                    with inner[1]:
                        st.markdown(
                            '<div class="calc-output">' + calc_result_html("權證價格", simulated) + "</div>",
                            unsafe_allow_html=True,
                        )

            with calc_cols[1]:
                with st.container(key=f"calc_reverse_{card_id}"):
                    inner = st.columns([0.95, 1.05], gap="small")
                    target_key = f"target_text_{card_id}"
                    if target_key not in st.session_state:
                        st.session_state[target_key] = format_input_number(item.get("targetPrice"))
                    with inner[0]:
                        target_price_raw = st.text_input("權證價格", key=target_key)
                    target_price = to_number(target_price_raw)
                    if target_price is None:
                        implied = None
                        if to_number(item.get("targetPrice")) is not None or to_number(item.get("impliedSpot")) is not None:
                            item["targetPrice"] = ""
                            item["impliedSpot"] = None
                            changed = True
                    else:
                        if numbers_equal(target_price, item.get("targetPrice")) and to_number(item.get("impliedSpot")) is not None:
                            implied = item.get("impliedSpot")
                        else:
                            implied = implied_spot_from_price(item, target_price)
                            item["impliedSpot"] = implied
                            item["targetPrice"] = target_price
                            changed = True
                    with inner[1]:
                        st.markdown(
                            '<div class="calc-output">' + calc_result_html("股價", implied) + "</div>",
                            unsafe_allow_html=True,
                        )

            if item.get("error"):
                st.markdown(error_note_html(item["error"]), unsafe_allow_html=True)


def render_mobile_warrant_card(item: dict[str, Any], index: int) -> None:
    card_id = safe_key(item.get("id") or item.get("code") or str(index))
    changed = False
    with st.container(border=False, key=f"mobile_card_{card_id}"):
        card_cols = st.columns([1.0, 0.12], gap="small")

        with card_cols[1]:
            with st.container(key=f"mobile_actions_{card_id}"):
                st.markdown('<div class="mobile-action-spacer"></div>', unsafe_allow_html=True)
                with st.container(key=f"mobile_btn_grid_{card_id}"):
                    btn_l, btn_r = st.columns(2)
                    with btn_l:
                        with st.container(key=f"mobile_action_up_{card_id}"):
                            if st.button("▲", key=f"m_up_{card_id}", disabled=index == 0, help="上移"):
                                move_item(index, -1)
                        with st.container(key=f"mobile_action_down_{card_id}"):
                            if st.button("▼", key=f"m_dn_{card_id}", disabled=index == len(st.session_state["items"]) - 1, help="下移"):
                                move_item(index, 1)
                    with btn_r:
                        with st.container(key=f"mobile_reset_{card_id}"):
                            with st.popover("↺", help="重置隱波紀錄"):
                                st.markdown("<div style='text-align: center; margin-bottom: 0.5rem; font-size: 0.85rem;'>確定重置隱波？</div>", unsafe_allow_html=True)
                                if st.button("確認", key=f"m_confirm_reset_{card_id}", use_container_width=True):
                                    reset_volatility_tracking(st.session_state["items"][index])
                                    st.rerun()
                        with st.container(key=f"mobile_delete_{card_id}"):
                            with st.popover("×", help="刪除這檔權證"):
                                st.markdown("<div style='text-align: center; margin-bottom: 0.5rem; font-size: 0.85rem;'>確定刪除？</div>", unsafe_allow_html=True)
                                if st.button("確認", key=f"m_confirm_del_{card_id}", use_container_width=True):
                                    delete_item(index)

        with card_cols[0]:
            st.markdown(
                '<div class="mobile-card-header">'
                '<div class="mobile-title">'
                f"{warrant_title_html(item)}"
                f"{detail_html(item)}"
                "</div>"
                '<div class="mobile-metrics">'
                + metric_html("合理價", valid_price(item.get("fairPrice")), accent=True, missing="---")
                + metric_html("報價", item.get("marketReference"))
                + metric_html("現貨股價", item.get("spot"), note=spot_source_note(item))
                + "</div>"
                "</div>",
                unsafe_allow_html=True,
            )

            with st.container(key=f"mobile_calc_row_{card_id}"):
                calc_cols = st.columns(2, gap="small")
                with calc_cols[0]:
                    with st.container(key=f"mobile_calc_forward_{card_id}"):
                        inner = st.columns([0.95, 1.05], gap="small")
                        spot_key = f"mobile_spot_text_{card_id}"
                        if spot_key not in st.session_state:
                            st.session_state[spot_key] = format_input_number(item.get("testSpot"))
                        with inner[0]:
                            test_spot_raw = st.text_input("股價", key=spot_key)
                        test_spot = to_number(test_spot_raw)
                        if test_spot is None:
                            simulated = None
                            if to_number(item.get("testSpot")) is not None or to_number(item.get("simulatedPrice")) is not None:
                                item["testSpot"] = ""
                                item["simulatedPrice"] = None
                                changed = True
                        else:
                            if numbers_equal(test_spot, item.get("testSpot")) and to_number(item.get("simulatedPrice")) is not None:
                                simulated = item.get("simulatedPrice")
                            elif numbers_equal(test_spot, item.get("spot")):
                                simulated = valid_price(item.get("fairPrice"))
                                changed = True
                            else:
                                simulated = fair_price_for_spot(item, test_spot)
                                changed = True
                            if changed:
                                item["testSpot"] = test_spot
                                item["simulatedPrice"] = simulated
                        with inner[1]:
                            st.markdown(
                                '<div class="mobile-calc-output">' + calc_result_html("權證價格", simulated) + "</div>",
                                unsafe_allow_html=True,
                            )

                with calc_cols[1]:
                    with st.container(key=f"mobile_calc_reverse_{card_id}"):
                        inner = st.columns([0.95, 1.05], gap="small")
                        target_key = f"mobile_target_text_{card_id}"
                        if target_key not in st.session_state:
                            st.session_state[target_key] = format_input_number(item.get("targetPrice"))
                        with inner[0]:
                            target_price_raw = st.text_input("權證價格", key=target_key)
                        target_price = to_number(target_price_raw)
                        if target_price is None:
                            implied = None
                            if to_number(item.get("targetPrice")) is not None or to_number(item.get("impliedSpot")) is not None:
                                item["targetPrice"] = ""
                                item["impliedSpot"] = None
                                changed = True
                        else:
                            if numbers_equal(target_price, item.get("targetPrice")) and to_number(item.get("impliedSpot")) is not None:
                                implied = item.get("impliedSpot")
                            else:
                                implied = implied_spot_from_price(item, target_price)
                                item["impliedSpot"] = implied
                                item["targetPrice"] = target_price
                                changed = True
                        with inner[1]:
                            st.markdown(
                                '<div class="mobile-calc-output">' + calc_result_html("股價", implied) + "</div>",
                                unsafe_allow_html=True,
                            )

            if item.get("error"):
                st.markdown(error_note_html(item["error"]), unsafe_allow_html=True)


def render_details(item: dict[str, Any]) -> None:
    quote = item.get("quote") or {}
    underlying_quote = item.get("underlyingQuote") or {}
    detail_line("類型", type_text(item.get("type") or "call"))
    detail_line("標的", f"{item.get('underlyingCode') or ''} {item.get('underlyingName') or ''}".strip())
    detail_line("履約價", format_number(item.get("strike")))
    detail_line("換股比例", format_number(item.get("ratio"), 4))
    detail_line("到期日", item.get("expiry") or "--")
    detail_line("評價日", item.get("evaluationDate") or "--")
    detail_line("合理價來源", item.get("fairPriceSource") or "--")
    detail_line("委買隱波", volatility_detail_text(item))
    detail_line("利率", f"{format_number((to_number(item.get('riskFreeRate')) or 0) * 100)}%")
    detail_line("委買/委賣", f"{format_number(quote.get('bestBid'))} / {format_number(quote.get('bestAsk'))}")
    detail_line("標的市場", f"{underlying_quote.get('market') or '--'}")


def render_desktop_watchlist() -> None:
    for row_start in range(0, len(st.session_state["items"]), 2):
        cols = st.columns(2, gap="small")
        for offset, col in enumerate(cols):
            item_index = row_start + offset
            if item_index >= len(st.session_state["items"]):
                continue
            with col:
                render_warrant_card(st.session_state["items"][item_index], item_index)


def render_mobile_watchlist() -> None:
    for item_index, item in enumerate(st.session_state["items"]):
        render_mobile_warrant_card(item, item_index)


def render_main() -> None:
    if not st.session_state["items"]:
        st.markdown(
            '<div class="empty-state"><strong>還沒有儲存任何權證</strong><br>從左側輸入代號後，系統會自動抓資料。</div>',
            unsafe_allow_html=True,
        )
        return

    with st.container(key="desktop_watchlist"):
        render_desktop_watchlist()
    with st.container(key="mobile_watchlist"):
        render_mobile_watchlist()


def render_mobile_controls() -> None:
    with st.container(key="mobile_controls"):
        mobile_notice = st.session_state.pop("_mobile_refresh_notice", "")
        if mobile_notice:
            st.toast(mobile_notice)
        st.markdown(
            f'<div class="mobile-status-summary">'
            f'<div class="mobile-status-count">已儲存 <strong style="color: var(--ink);">{len(st.session_state["items"])}</strong> 檔</div>'
            f'<div>評價日期: {today_compact()} | {html.escape(app_version_text())} | 儲存: {html.escape(storage_label())}</div>'
            f'<div class="mobile-status-updated">最近更新 {html.escape(latest_update_text(st.session_state["items"]))}</div>'
            f'</div>',
            unsafe_allow_html=True,
        )

        btn_cols = st.columns(2, gap="small")
        with btn_cols[0]:
            with st.popover("新增", use_container_width=True):
                with st.form("add_warrant_form_mobile", clear_on_submit=True):
                    code = st.text_input("權證代號", placeholder="例如 030012", key="mobile_warrant_code").strip().upper()
                    submitted = st.form_submit_button("新增並抓資料", use_container_width=True)
                if submitted:
                    try:
                        add_or_update_warrant(code)
                    except Exception as error:
                        st.error(str(error))
        with btn_cols[1]:
            if st.button("更新價格", use_container_width=True, disabled=not st.session_state["items"], key="mobile_refresh_prices"):
                try:
                    with st.spinner("更新價格中，請等這行消失..."):
                        failed = refresh_all_prices()
                    st.session_state["_mobile_refresh_notice"] = f"已更新，{failed} 檔暫時抓不到" if failed else "價格已更新"
                    st.rerun()
                except Exception as error:
                    st.error(str(error))
            with st.container(key="mobile_backup_controls"):
                backup_cols = st.columns(2, gap="small")
                with backup_cols[0]:
                    st.download_button(
                        "匯出資料",
                        data=export_items_text(),
                        file_name=f"warrant_watch_{today_compact()}.json",
                        mime="application/json",
                        use_container_width=True,
                        key="mobile_export_items",
                    )
                with backup_cols[1]:
                    with st.popover("匯入資料", use_container_width=True):
                        raw_text = st.text_area("貼上備份 JSON", key="mobile_import_items_text", height=140)
                        replace = st.checkbox("取代目前清單", value=True, key="mobile_import_replace")
                        if st.button("確認匯入", use_container_width=True, key="mobile_import_submit"):
                            try:
                                count = import_items(raw_text, replace=replace)
                                st.toast(f"已匯入 {count} 檔")
                                st.rerun()
                            except Exception as error:
                                st.error(str(error))


def render_sidebar() -> None:
    with st.sidebar:
        st.title("Warrant Watch!")
        st.markdown(
            f'<div style="color: var(--faint); font-size: 0.68rem; line-height: 1.5; margin-bottom: 0.8rem; word-wrap: break-word; white-space: normal;">'
            f'評價日期: {today_compact()}<br>'
            f'{html.escape(app_version_text())}<br>'
            f'儲存: {html.escape(storage_label())}'
            f'</div>',
            unsafe_allow_html=True,
        )

        with st.form("add_warrant_form", clear_on_submit=True):
            code = st.text_input("權證代號", placeholder="例如 030012").strip().upper()
            submitted = st.form_submit_button("新增並抓資料", use_container_width=True)
        if submitted:
            try:
                add_or_update_warrant(code)
            except Exception as error:
                st.error(str(error))

        status_cols = st.columns([0.42, 0.58], gap="small")
        with status_cols[0]:
            st.markdown(
                '<div class="sidebar-status">'
                f'<span>已儲存 <strong>{len(st.session_state["items"])}</strong> 檔</span>'
                "</div>",
                unsafe_allow_html=True,
            )
        with status_cols[1]:
            if st.button("更新價格", use_container_width=True, disabled=not st.session_state["items"]):
                try:
                    refresh_all_prices()
                except Exception as error:
                    st.error(str(error))
        with st.container(key="desktop_backup_row"):
            backup_row_cols = st.columns([0.52, 0.48], gap="small")
            with backup_row_cols[0]:
                with st.container(key="desktop_backup_buttons"):
                    backup_cols = st.columns(2, gap="small")
                    with backup_cols[0]:
                        st.download_button(
                            "匯出資料",
                            data=export_items_text(),
                            file_name=f"warrant_watch_{today_compact()}.json",
                            mime="application/json",
                            use_container_width=True,
                            key="desktop_export_items",
                        )
                    with backup_cols[1]:
                        with st.popover("匯入資料", use_container_width=True):
                            raw_text = st.text_area("貼上備份 JSON", key="desktop_import_items_text", height=140)
                            replace = st.checkbox("取代目前清單", value=True, key="desktop_import_replace")
                            if st.button("確認匯入", use_container_width=True, key="desktop_import_submit"):
                                try:
                                    count = import_items(raw_text, replace=replace)
                                    st.toast(f"已匯入 {count} 檔")
                                    st.rerun()
                                except Exception as error:
                                    st.error(str(error))
            with backup_row_cols[1]:
                st.markdown(
                    f'<div class="sidebar-update-inline">最近更新 {html.escape(latest_update_text(st.session_state["items"]))}</div>',
                    unsafe_allow_html=True,
                )


def main() -> None:
    st.set_page_config(page_title="權證合理價", page_icon=BytesIO(base64.b64decode(FAVICON_PNG_BASE64)), layout="wide", initial_sidebar_state="expanded")
    inject_toolbar_css()
    inject_css()
    if "items" not in st.session_state:
        st.session_state["items"] = read_cloud_items()
    sync_session_version()
    reset_calculation_state_once()
    render_sidebar()
    render_mobile_controls()
    render_main()


if __name__ == "__main__":
    main()


